def numberOfJumps(n):
    n = abs(n)
    j = 0
    while True:
        s = j*(j+1)//2
        if s >= n and not (s - n)%2:
            break
        j += 1
    return j

print(numberOfJumps(int(input())))

#!/usr/bin/env python

def findJumps (dest, jumps, l, maxHops) :
    if (len(l) > maxHops) :
        return []
    if (dest == sum(l)) :
        return l

    l1 = l[:]
    l2 = l[:]
    l1.append(jumps + 1)
    l2.append(-(jumps + 1))

    ret = findJumps (dest, jumps + 1, l1, maxHops)
    if (len(ret) > 0) :
        return ret
    return findJumps (dest, jumps + 1, l2, maxHops)

def findShortest (dest) :
    dest = abs(dest)
    if dest == 0:
        return 0
    n = 0
    total = 0
    while total < dest or (total - dest) % 2 != 0:
        n += 1
        total += n
    return n

dest = int(input())
print(findShortest(dest))

